mapper.select:
SELECT id, user_id AS userId, order_id AS orderId, operator_id AS operatorId, transaction_no AS transactionNo, type, amount, balance_before AS balanceBefore, balance_after AS balanceAfter, status, remark, created_at AS createdAt, updated_at AS updatedAt, operator_id AS operatorId FROM tb_jmz_transactions
AND user_id = #{query.userId}
AND type = #{query.type} AND created_at >= #{query.startTime} AND created_at <= #{query.endTime}
ORDER BY created_at DESC
